import com.comsol.model.*;import com.comsol.model.util.*;
public class MeshStateAudit {public static void main(String[] a){try{ModelUtil.initStandalone(false);Model m=ModelUtil.load("m",a[0]);String s=ExportNative.savedSolution(m);ExportNative.dataset(m,s);
m.component("c").cpl().create("minAll","Minimum");m.component("c").cpl("minAll").selection().all();m.component("c").cpl("minAll").set("opname","minAll");m.component("c").cpl().create("maxBoundary","Maximum");m.component("c").cpl("maxBoundary").selection().geom("g",1);m.component("c").cpl("maxBoundary").selection().named("surface");m.component("c").cpl("maxBoundary").set("opname","maxBoundary");
String[] ex={"c.spatial.relVolMin","c.spatial.minqual","c.minAll(spatial.relVol)","c.maxBoundary(abs(c.uzCu))","c.maxBoundary(abs(c.urCu))","c.maxBoundary(abs(c.vnSurf-c.vnPhysical))"};m.sol(s).updateSolution();m.result().numerical().create("state","EvalGlobal");m.result().numerical("state").set("data","dset1");m.result().numerical("state").set("expr",ex);ExportNative.csv(a[1],ex,m.sol(s).getPVals(),m.result().numerical("state").getReal());System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}}
